                    M.tp(CFrame.new(p + Vector3.new(0, 1, 5)))
                    task.wait(0.3)
                    M.fire("PlaceStoneInMachineEvent", e.m, s.Name)
                    task.wait(0.4)
                    did = true
                end
            end
        end
    end
    return did
end
function F.tooSlow(s)
    local res = s:GetAttribute("Resistance") or 0
    local maxT = (tonumber(val("f_maxcut", 30)) or 30) * 60
    local list = F.machines()
    if #list == 0 then return false end
    for _, e in ipairs(list) do
        if F.canCut(e.lvl, res) and F.cutTime(e.lvl, res) <= maxT then return false end
    end
    return true
end
F.surplus = {}
function F.markSurplus()
    table.clear(F.surplus)
    local w, cap = F.bag()
    if w < cap * 0.75 then return end
    local keep = math.max(#F.machines() * 2, 4)
    local list = F.uncut()
    for i = keep + 1, #list do F.surplus[list[i]] = true end
end
function F.sellNow()
    local inv = lp:FindFirstChild("Envanter")
    if not inv then return end
    F.markSurplus()
    local ids = {}
    for _, s in ipairs(inv:GetChildren()) do
        local cut = s:GetAttribute("Kesildi") == true
        local slow = not cut and on("f_sellslow") and (F.tooSlow(s) or F.surplus[s])
        if s:GetAttribute("Kilitli") ~= true and s:GetAttribute("Kesimde") ~= true and (cut or slow or on("f_selluncut")) then
            ids[#ids + 1] = s:GetAttribute("Uid") or s.Name
        end
    end
    if #ids == 0 then return end
    local m0 = M.money()
    M.fire("SellEvent", "SellSelected", ids)
    task.wait(0.6)
    if M.money() > m0 then S.sold += #ids S.earned += M.money() - m0 end
end
function F.needsMachine()
    local list = F.machines()
    for _, e in ipairs(list) do
        if e.state == "Hazir" and (e.owner == nil or e.owner == lp.UserId) then return true end
    end
    local stones = F.uncut()
    if #stones == 0 then return false end
    local maxT = (tonumber(val("f_maxcut", 30)) or 30) * 60
    for _, e in ipairs(list) do
        if e.state == "Bos" or e.state == nil then
            for _, s in ipairs(stones) do
                local res = s:GetAttribute("Resistance") or 0
                if F.canCut(e.lvl, res) and F.cutTime(e.lvl, res) <= maxT then return true end
            end
        end
    end
    return false
end
local P = { mem = 0 }
function P.indexDone()
    local disc = lp:FindFirstChild("IndexKesifleri")
    if not (disc and D.Rocks) then return 0 end
    local found = {}
    for _, c in ipairs(disc:GetChildren()) do
        local rock = c.Name:match("^(.-)|")
        if rock and rock ~= "Tas" then found[rock] = (found[rock] or 0) + 1 end
    end
    local n = 0
    for _, list in ipairs({ D.Rocks.Rarety or {}, D.Rocks.Limited or {} }) do
        for _, r in ipairs(list) do
            local need = r.material_list and #r.material_list or 5
            if need > 0 and (found[r.Name] or 0) >= need then n += 1 end
        end
    end
    return n
end
function P.station()
    local ok, ist = pcall(function() return Workspace.Models.World.AfkFarm.Istasyonlar end)
    if not ok or not ist then return nil end
    local done = P.indexDone()
    local best, bc
    for _, s in ipairs(ist:GetChildren()) do
        local c = s:GetAttribute("Carpan") or 1
        local open = (s:GetAttribute("GerekenKat") == nil and s:GetAttribute("GerekenIndex") == nil)
            or (s:GetAttribute("GerekenKat") and M.n("MaximumRoom") >= s:GetAttribute("GerekenKat"))
            or (s:GetAttribute("GerekenIndex") and done >= s:GetAttribute("GerekenIndex"))
            or lp:GetAttribute("RobuxOrs_" .. tostring(c)) == true
        if open and (not bc or c > bc) then best, bc = s, c end
    end
    return best, bc
end
function P.goAnvil()
    local st = P.station()
    if not st then return false end
    local dn = st:FindFirstChild("DurmaNoktasi") or st:FindFirstChild("TrainAlani")
    if not dn then return false end
    local r = M.root()
    if r and (r.Position - dn.Position).Magnitude < 5 and M.n("TrainOrsu") > 0 then return true end
    M.leaveMine()
    M.tp(dn.CFrame + Vector3.new(0, 3, 0))
    task.wait(0.8)
    return true
end
function P.memoryRound()
    local ok, r = M.inv("MemoryOyunu", "Basla")
    if not (ok and type(r) == "table" and r.ok and type(r.sira) == "table") then
        P.memFail = os.clock()
        return false
    end
    local z = r.zaman or {}
    local need = (z.bekleme or 0.6) + (z.yanma or 0.55) * #r.sira + 0.3
    local t0 = os.clock()
    while os.clock() - t0 < need and RUNNING do task.wait(0.05) end
    local ok2, r2 = M.inv("MemoryOyunu", "Cevap", r.sira)
    if ok2 and type(r2) == "table" and r2.durum == "basarili" then
        S.memory += 1
        return true
    end
    LOG("memory fail", ok2 and type(r2) == "table" and tostring(r2.durum) or "?")
    return false
end
function P.floorOf(b)
    local room = b:FindFirstAncestorWhichIsA("Model")
    local depth = room and room:GetAttribute("Depth") or 0
    return depth + (b.Parent and b.Parent.Name == "ExitDigBlocks" and 2 or 1)
end
function P.digTarget()
    local best, bf
    local reached = M.n("MaximumRoom")
    for _, b in ipairs(CollectionService:GetTagged("DigBlock")) do
        if b:IsA("BasePart") and b.CanCollide and b.Parent then
            local f = P.floorOf(b)
            if f > reached and (not bf or f < bf) then best, bf = b, f end
        end
    end
    return best, bf
end
function P.digStep()
    local b = P.digTarget()
    if not b then S.task = __T["All floors open"] return false end
    local hp = b:GetAttribute("MaxHealth") or math.huge
    local maxHits = tonumber(val("p_maxhits", 120)) or 120
    if hp / math.max(M.power(), 1) > maxHits then S.task = __T["Need more power to dig"] return false end
    S.task = __T["Digging floor"]
    local top = b.Position + Vector3.new(0, b.Size.Y / 2 + 3, 0)
    M.tp(CFrame.new(top))
    task.wait(0.3)
    local t0 = os.clock()
    while RUNNING and on("p_dig") and b.CanCollide and b.Parent and os.clock() - t0 < 60 and J.list[1] == nil do
        local r = M.root()
        if not r then break end
        if (r.Position - top).Magnitude > 4 then M.tp(CFrame.new(top)) task.wait(0.2) end
        M.fire("KapiVurusu", b, Workspace:GetServerTimeNow(), M.root().Position)
        task.wait(0.52)
    end
    if not b.CanCollide then S.floors += 1 LOG("floor broken", b:GetFullName()) end
    return true
end
local U = { fails = {} }
function U.tick()
    if on("u_pocket") then
        local lv = M.n("PocketLevel")
        local price = D.Upgrade and D.Upgrade.pocket_price and D.Upgrade.pocket_price[lv + 1]
        if price and M.spendable() >= price and not (U.fails.pocket and os.clock() < U.fails.pocket) then
            M.fire("UpgradeEvent", "Pocket", M.seq())
            task.wait(0.6)
            if M.n("PocketLevel") > lv then S.bought += 1 else U.fails.pocket = os.clock() + 5 end
        end
    end
    if on("u_sight") then
        local lv = M.n("Sight")
        local price = D.Upgrade and D.Upgrade.sight_price and D.Upgrade.sight_price[lv + 1]
        if price and M.spendable() >= price and not (U.fails.sight and os.clock() < U.fails.sight) then
            M.fire("UpgradeEvent", "Eyesight", M.seq())
            task.wait(0.6)
            if M.n("Sight") > lv then S.bought += 1 else U.fails.sight = os.clock() + 5 end
        end
    end
    local list = D.Pickaxe and D.Pickaxe.Normal
    local owned = lp:FindFirstChild("KazmaSahipligi")
    if list and owned then
        local best = 1
        for i = 1, #list do if owned:FindFirstChild(tostring(i)) then best = i end end
        if on("u_pick") then
            local nextRow = list[best + 1]
            if nextRow and (nextRow.Price or 0) > 0 and M.spendable() >= nextRow.Price and not (U.fails.pick and os.clock() < U.fails.pick) then
                M.fire("PickaxeBuyEvent", best + 1)
                task.wait(0.7)
                if owned:FindFirstChild(tostring(best + 1)) then S.bought += 1 best += 1 else U.fails.pick = os.clock() + 5 end
            end
        end
        if on("u_pick") and M.n("KusanilanKazma") ~= best and not (U.eqAt and os.clock() - U.eqAt < 3) then
            U.eqAt = os.clock()
            M.fire("PickaxeEquipEvent", best, M.seq())
        end
    end
    if on("u_level") and D.Machine and D.Machine.Fiyatlar then
        local cheapest
        for _, e in ipairs(F.machines()) do
            local price = D.Machine.Fiyatlar[e.lvl + 1]
            if price and (not cheapest or price < cheapest.price) then cheapest = { m = e.m, price = price, lvl = e.lvl } end
        end
        if cheapest and M.spendable() >= cheapest.price and not (U.fails.lvl and os.clock() < U.fails.lvl) then
            M.fire("LevelUpMachineEvent", cheapest.m, M.seq())
            task.wait(0.7)
            if (cheapest.m:GetAttribute("Seviye") or 0) > cheapest.lvl then S.bought += 1 else U.fails.lvl = os.clock() + 5 end
        end
    end
    if on("u_machine") then
        for _, d in ipairs(F.prompts().buy) do
            if d.Parent and d.Enabled then
                local raw = tostring(d.ObjectText):match("^([%d%.]+)([KMBT]?)%$")
                local num, suf = tostring(d.ObjectText):match("^([%d%.]+)([KMBT]?)%$")
                local mult = ({ K = 1e3, M = 1e6, B = 1e9, T = 1e12 })[suf or ""] or 1
                local price = raw and tonumber(num) and tonumber(num) * mult or nil
                if price and M.spendable() >= price and not J.keys.buymachine then
                    J.push("buymachine", function()
                        local p = M.promptPos(d)
                        if not p then return end
                        S.task = __T["Buying a machine"]
                        M.tp(CFrame.new(p + Vector3.new(0, 1, 5)))
                        task.wait(0.4)
                        M.press(d)
                        task.wait(0.8)
                        F.pCache = nil
                        S.bought += 1
                    end)
                    break
                end
            end
        end
    end
end
